  summary: 'Reproduce a game',
  board: 'Board code',
  loadBoard: 'Load board',
  snapshot: 'Snapshot JSON',
  exportSnapshot: 'Export snapshot',
  loadSnapshot: 'Load snapshot',
  resume: 'Resume',
} as const;
.reproduction {
  margin-top: 24px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--panel);
}
.reproduction > summary {
  min-height: 44px;
  padding: 12px 16px;
  font: inherit;
  cursor: pointer;
}
.reproduction-body {
  padding: 4px 16px 16px;
  display: grid;
  gap: 12px;
}
.reproduction form {
  display: grid;
  gap: 6px;
}
.control-row {
  display: flex;
  align-items: end;
  flex-wrap: wrap;
  gap: 12px;
}
.reproduction input {
  flex: 1;
  width: 16ch;
}
.reproduction textarea {
  width: 100%;
  resize: vertical;
}
@media (max-width: 599px) {
  .control-row > button {
    flex: 1;
  }
}
.load-status {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  min-height: 56px;
  margin: 4px 0 8px;
}
.load-status p {
  flex: 1;
  min-width: 0;
}
